import { useMutation, useQueryClient } from '@tanstack/react-query'

type Todo = { id: number; title: string }

async function updateTodo(todo: Todo): Promise<Todo> {
  const response = await fetch(`/api/todos/${todo.id}`, {
    method: 'PUT',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(todo),
  })
  if (!response.ok) throw new Error('Update failed')
  return response.json()
}

export function useUpdateTodo() {
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: updateTodo,
    onMutate: async (todo) => {
      await queryClient.cancelQueries({ queryKey: ['todos'] })
      const previous = queryClient.getQueryData<Todo[]>(['todos'])
      queryClient.setQueryData<Todo[]>(['todos'], (items = []) =>
        items.map(item => item.id === todo.id ? todo : item),
      )
      return { previous }
    },
    onError: (_error, _todo, context) => {
      queryClient.setQueryData(['todos'], context?.previous)
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ['todos'] })
    },
  })
}

import { useMutation, useQueryClient } from '@tanstack/react-query'

type Todo = { id: number; title: string }

async function addTodo(todo: Todo) {
  const response = await fetch('/api/todos', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(todo),
  })
  if (!response.ok) throw new Error('Request failed')
  return response.json()
}

export function AddTodo() {
  const queryClient = useQueryClient()
  const mutation = useMutation({
    mutationFn: addTodo,
    onMutate: async (newTodo) => {
      await queryClient.cancelQueries({ queryKey: ['todos'] })
      const previousTodos = queryClient.getQueryData<Todo[]>(['todos'])
      queryClient.setQueryData<Todo[]>(['todos'], (old = []) => [...old, newTodo])
      return { previousTodos }
    },
    onError: (_error, _newTodo, context) => {
      queryClient.setQueryData(['todos'], context?.previousTodos)
    },
    onSettled: () => queryClient.invalidateQueries({ queryKey: ['todos'] }),
  })

  return <button onClick={() => mutation.mutate({ id: Date.now(), title: 'Learn Query' })}>Add</button>
}

