import { QueryClient, QueryClientProvider, useQuery } from '@tanstack/react-query'
import { useEffect } from 'react'

const queryClient = new QueryClient()
const fetchProjects = (page: number) =>
  fetch(`/api/projects?page=${page}`).then((r) => r.json())

function Projects({ page }: { page: number }) {
  const nextPage = page + 1
  const { data } = useQuery({
    queryKey: ['projects', page],
    queryFn: () => fetchProjects(page),
  })

  useEffect(() => {
    if (data?.hasMore) {
      queryClient.prefetchQuery({
        queryKey: ['projects', nextPage],
        queryFn: () => fetchProjects(nextPage),
      })
    }
  }, [data, nextPage])

  return <button>Next page</button>
}

import { useInfiniteQuery } from '@tanstack/react-query'

async function fetchPage({ pageParam }: { pageParam: number }) {
  const response = await fetch(`/api/items?cursor=${pageParam}`)
  return response.json() as Promise<{ items: string[]; nextCursor?: number }>
}

export function Items() {
  const query = useInfiniteQuery({
    queryKey: ['items'],
    queryFn: fetchPage,
    initialPageParam: 0,
    getNextPageParam: (lastPage) => lastPage.nextCursor,
  })

  return (
    <>
      {query.data?.pages.flatMap((page) => page.items).map((item) => (
        <div key={item}>{item}</div>
      ))}
      <button
        disabled={!query.hasNextPage || query.isFetchingNextPage}
        onClick={() => query.fetchNextPage()}
      >
        {query.isFetchingNextPage ? 'Loading…' : 'Load more'}
      </button>
    </>
  )
}

